> *This section details on the original issue you should resolve*
> 
> <issue_title>FlagIcon 项目重做</issue_title>
> <issue_description>1. 删除 LuYao.Avalonia.Controls.FlagIcon 项目
> 2. FlagIcon 不再是一个单独的控件，而是可以附加到 Image 控件的独立类型。
> 3. 将所有图片打包为一个完整的雪碧图，分发时，只分发雪碧图。
> 4. 预购键小图片，尺寸 20:15 像素。FlagIcon 支持设置是否使用小图片。</issue_description>
> 
> <agent_instructions>你可以参考如下代码
> ```csharp
> using System;
> using System.Collections.Generic;
> using System.Reflection;
> using Avalonia;
> using Avalonia.Controls;
> using Avalonia.Media;
> using Avalonia.Media.Imaging;
> using Avalonia.Platform;
> using LuYao;
> 
> namespace Popcorn.Toolkit.UI.Controls;
> 
> public class EIcon
> {
>     private static readonly IReadOnlyDictionary<EIcons, IImage> Cache;
> 
>     public static readonly AttachedProperty<EIcons> IconProperty =
>         AvaloniaProperty.RegisterAttached<EIcon, Image, EIcons>("Icon");
> 
>     static EIcon()
>     {
>         var dict = new Dictionary<EIcons, IImage>();
> 
>         using (var ms = AssetLoader.Open(new Uri("avares://Popcorn.Toolkit.UI/Assets/Images/sprite.png")))
>         {
>             var bmp = new Bitmap(ms);
>             var t = typeof(EIcons);
>             foreach (var ico in Enum<EIcons>.GetValues())
>             {
>                 string n = ico.ToString();
>                 FieldInfo? f = t.GetField(n);
>                 if (f == null) continue;
>                 var attr = f.GetCustomAttribute<EIconRectangleAttribute>();
>                 if (attr == null) continue;
>                 var flag = new CroppedBitmap(bmp, new PixelRect(attr.X, attr.Y, attr.Width, attr.Height));
>                 dict[ico] = flag;
>             }
>         }
> 
>         Cache = dict;
>         IconProperty.Changed.AddClassHandler<Image>(OnIconChanged);
>     }
> 
>     // 必须添加 Get 和 Set 方法
>     public static EIcons GetIcon(Image image)
>     {
>         return image.GetValue(IconProperty);
>     }
> 
>     public static void SetIcon(Image image, EIcons value)
>     {
>         image.SetValue(IconProperty, value);
>     }
> 
>     private static void OnIconChanged(Image image, AvaloniaPropertyChangedEventArgs e)
>     {
>         if (e.NewValue != e.OldValue && e.NewValue is EIcons icon)
>         {
>             image.Source = Cache.GetValueOrDefault(icon);
>         }
>     }
> }
> ```
> ------
> ```csharp
> class EIconRectangleAttribute(int x, int y, int width, int height) : Attribute
> {
>     public int X { get; } = x;
> 
>     public int Y { get; } = y;
> 
>     public int Width { get; } = width;
> 
>     public int Height { get; } = height;
> }
> ```</agent_instructions>
